mapper.select:
SELECT admin_id, username, email, password_hash, display_name,
       role, enabled, created_at, updated_at, last_login_at
  FROM id_admin
 WHERE username = #{usernameOrEmail}
    OR email    = #{usernameOrEmail}
 LIMIT 1

mapper.insert:
INSERT INTO id_admin (
  admin_id, username, email, password_hash, display_name, role, enabled
) VALUES (
  #{adminId}, #{username}, #{email}, #{passwordHash}, #{displayName},
  #{role}, #{enabled}
)

mapper.update:
UPDATE id_admin
   SET last_login_at = CURRENT_TIMESTAMP
 WHERE admin_id = #{adminId}

UPDATE id_admin
   SET password_hash = #{passwordHash},
       email         = #{email},
       role          = #{role},
       enabled       = #{enabled}
 WHERE username = #{username}
